import { useEffect, useState, useRef, type ReactNode, type FormEvent } from 'react';
import { ArrowRight, ArrowLeft, Plus, House, Users, Path, Books, ChatCircle, Check, CheckCircle, Clock, MagnifyingGlass, X, UploadSimple, PencilSimple, Info, SignOut, LockSimple, PaperPlaneTilt, WarningCircle, FileText, CaretRight, Trash } from '@phosphor-icons/react';
import type { State, Employee, Template, Article, Request, Role, Track, Format } from './types';

const tracks:Record<Track,string>={warehouse:'Склад',store:'Магазин',sales:'Продажи',office:'Офис и e-commerce'};
const formats:Record<Format,string>={onsite:'На площадке',remote:'Удалённо',hybrid:'Гибридно',unknown:'Нужно уточнить'};
const statuses={new:'Нужен ответ',progress:'В работе',waiting:'Ждём подтверждения',resolved:'Помощь сработала'};
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const uid=()=>crypto.randomUUID();
const plural=(n:number,one:string,few:string,many:string)=>n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;
const stamp=(s:string)=>new Date(s).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
async function api<T>(url:string, body?:unknown):Promise<T>{const r=await fetch(url,body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).catch(()=>{throw new Error('Не удалось связаться с локальным сервером. Проверьте соединение и повторите действие. Введённые данные сохранены в форме.');});const j=await r.json();if(!r.ok)throw new Error(j.error||'Не удалось сохранить. Попробуйте ещё раз.');return j as T;}
function Badge({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>}
function Heading({title,sub,action}:{title:string;sub?:string;action?:ReactNode}){return <div className="heading"><div><h1>{title}</h1>{sub&&<p className="muted">{sub}</p>}</div>{action}</div>}
function Empty({children}:{children:ReactNode}){return <div className="empty"><CheckCircle size={32}/><p>{children}</p></div>}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small className="muted">{hint}</small>}</label>}
function Modal({title,children,close}:{title:string;children:ReactNode;close:()=>void}){
 const ref=useRef<HTMLElement>(null);const closeRef=useRef(close);closeRef.current=close;
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const old=document.body.style.overflow;document.body.style.overflow='hidden';
  const items=()=>Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),a[href],summary')||[]).filter(e=>e.offsetParent!==null);
  items()[0]?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const a=items(),first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};
  window.addEventListener('keydown',key);return()=>{window.removeEventListener('keydown',key);document.body.style.overflow=old;previous?.focus()};},[]);
 return <div className="modal-shade" onClick={e=>{if(e.target===e.currentTarget)close()}}><section ref={ref} className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="Закрыть"><X size={22}/></button></div>{children}</section></div>
}
function Journey({completed,total}:{completed:number;total:number}){const current=completed===0?0:completed<total?1:2;return <div className="journey">{['Старт','Первая задача','Самостоятельно','Итоги'].map((v,i)=><div className={`milestone ${i<current?'done':''} ${i===current?'current':''}`} key={v}><span>{i<current?<Check weight="bold" size={13}/>:i===current?<span className="inner-dot"/>:null}</span><small>{v}</small></div>)}</div>}

type Act=(action:string,payload:unknown)=>Promise<unknown>;
export function App(){
 const [role,setRole]=useState<Role>('hr'),[view,setView]=useState('today'),[data,setData]=useState<State|null>(null),[catalog,setCatalog]=useState<{id:string;name:string;role:string}[]>([]),[employeeId,setEmployeeId]=useState(''),[selected,setSelected]=useState(''),[error,setError]=useState(''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState(''),[editing,setEditing]=useState<Template|null>(null),[article,setArticle]=useState<Article|null>(null),[prefill,setPrefill]=useState(''),[initialTried,setInitialTried]=useState<string[]>([]);
 const generation=useRef(0);
 const load=async()=>{const sequence=++generation.current;const cat=await api<{employees:{id:string;name:string;role:string}[]}>('/api/catalog');if(sequence!==generation.current)return;setCatalog(cat.employees);const eid=cat.employees.some(e=>e.id===employeeId)?employeeId:cat.employees.find(e=>e.name.startsWith('Алина'))?.id||cat.employees[0]?.id;
  const s=await api<State>(`/api/state?role=${role}&employeeId=${eid}`);if(sequence!==generation.current)return;if(eid!==employeeId)setEmployeeId(eid);setData(s);};
 useEffect(()=>{let alive=true;setError('');load().catch(e=>alive&&setError(e.message));return()=>{alive=false}},[role,employeeId]);
 useEffect(()=>{const timer=setInterval(()=>load().catch(()=>{}),15000);return()=>clearInterval(timer)},[role,employeeId]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 const act:Act=async(action,payload)=>{setBusy(true);setError('');try{const r=await api<{result:unknown}>('/api/action',{action,payload,role});await load();return r.result;}catch(e){setError((e as Error).message);throw e;}finally{setBusy(false)}};
 const go=(v:string,id='')=>{setError('');setView(v);if(id)setSelected(id);window.scrollTo({top:0,behavior:'instant'})};
 const switchRole=(r:Role)=>{if(r!==role){generation.current++;setData(null)}setRole(r);setView(r==='employee'?'day':'today');setSelected('');setError('');};
 const ask=(q='',articleId='')=>{setPrefill(q);setInitialTried(articleId?[articleId]:[]);go('ask')};
 const openArticle=(a:Article|null)=>{setArticle(a);setModal('article')};
 const e=data?.employees.find(e=>e.id===employeeId)||data?.employees[0];
 const template=e&&data?.templates.find(t=>t.id===e.templateId);
 const templateFor=(person:Employee)=>data!.templates.find(t=>t.id===person.templateId)!;
 const nav=role==='employee'?[{id:'day',title:'Мой день',icon:House},{id:'myquestions',title:'Мои вопросы',icon:ChatCircle},{id:'knowledge',title:'Ответы',icon:Books}]:[{id:'today',title:'Сегодня',icon:House},{id:'people',title:'Новички',icon:Users},{id:'templates',title:'Маршруты',icon:Path},{id:'knowledge',title:'База ответов',icon:Books}];
 const showError=(e:unknown)=>setError(e instanceof Error?e.message:'Не удалось выполнить действие');
 const openRequest=(r:Request)=>{setSelected(r.id);go('request')};
 const addEmployee=()=>setModal('employee');
 const reset=async()=>{if(!confirm('Сбросить все изменения в локальной демонстрации?'))return;try{await api('/api/reset',{confirm:'reset-demo'});setEmployeeId('');setSelected('');setView(role==='employee'?'day':'today');await load();setToast('Учебные примеры восстановлены');}catch(e){showError(e)}};
 const header=<><div className="demo-bar"><span><span className="live-dot"/>Локальное демо · вымышленные сотрудники</span><div className="role-switch" aria-label="Роль для проверки">{([['employee','Сотрудник'],['hr','HR'],['mentor','Руководитель']] as const).map(([id,label])=><button key={id} className={role===id?'active':''} disabled={busy} onClick={()=>switchRole(id)}>{label}</button>)}</div><button className="demo-reset" onClick={()=>setModal('about')}>О демо</button></div></>;
 if(!data||!e||!template)return <>{header}<div className="loading"><span className="brand">разбег</span><p>{error||'Готовим ваш рабочий день…'}</p>{error&&<button className="primary" onClick={()=>load().catch(showError)}>Попробовать снова</button>}</div></>;
 const contextualDays=e.day===0?'До выхода':`День ${e.day}`;
 return <>{header}<div className={`shell ${role==='employee'?'employee-shell':''}`}><aside className="sidebar"><button className="logo" onClick={()=>go(role==='employee'?'day':'today')}><span className="brand">разбег</span></button><nav>{nav.map(n=><button key={n.id} className={view===n.id||(view==='request'&&n.id===(role==='employee'?'myquestions':'today'))?'active':''} onClick={()=>go(n.id)}><n.icon size={21}/>{n.title}{n.id==='today'&&data.requests.some(r=>r.status==='new')&&<span className="nav-count">{data.requests.filter(r=>r.status==='new').length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="user-row"><span className="avatar">{role==='employee'?e.name[0]:role==='hr'?'Е':'Д'}</span><div><strong>{role==='employee'?e.name.split(' ')[0]:role==='hr'?'Елена':'Наставник'}</strong><small>{role==='employee'?e.role:role==='hr'?'HR-куратор':'Руководитель'}</small></div></div><button className="text-button muted" onClick={()=>setModal('about')}><Info size={16}/> О подходе</button></div></aside><main className="main"><div className="topline"><span>{role==='employee'?'Ваш план':role==='hr'?'Адаптация сотрудников':'Команда'}</span>{role==='employee'?<select aria-label="Вымышленный сотрудник" value={employeeId} onChange={ev=>{if(ev.target.value!==employeeId){generation.current++;setData(null);setEmployeeId(ev.target.value)}go('day')}}>{catalog.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select>:<span className="demo-label">Демо</span>}</div>{error&&<div className="error-banner" role="alert"><WarningCircle size={20}/><span>{error}</span><button aria-label="Закрыть ошибку" onClick={()=>setError('')}><X size={18}/></button></div>}
 {role==='employee'&&view==='day'&&<><Heading title="Мой день" sub={`${e.role} · ${formats[template.format]} · ${contextualDays}`}/><div className="employee-layout"><section><Journey completed={e.completed.filter(s=>template.steps.some(t=>t.id===s)).length} total={template.steps.length}/><div className="next-task"><p className="eyebrow">Следующий шаг</p><h2>{template.steps.find(s=>!e.completed.includes(s.id))?.title||'Обсудить результат с наставником'}</h2><p>{template.steps.find(s=>!e.completed.includes(s.id))?.detail||'Все шаги маршрута отмечены. Вместе с наставником проверьте, что получается самостоятельно.'}</p><button className="primary" onClick={()=>{setSelected(template.steps.find(s=>!e.completed.includes(s.id))?.id||template.steps[0].id);setModal('step')}}>Открыть задачу <ArrowRight size={20}/></button></div><div className="step-list">{template.steps.map(s=><button className="step-row" key={s.id} onClick={()=>{setSelected(s.id);setModal('step')}}><span className={`check-circle ${e.completed.includes(s.id)?'checked':''}`}>{e.completed.includes(s.id)&&<Check size={14} weight="bold"/>}</span><span>{s.title}<small>{s.stage}</small></span><CaretRight size={16}/></button>)}</div><div className="mobile-contact"><Users size={23}/><div><small>Ваш наставник</small><strong>{e.mentor}</strong></div><button className="secondary" onClick={()=>ask()}>Задать вопрос</button></div><button className="checkin-entry" onClick={()=>go('checkin')}><ChatCircle size={25}/><span><strong>Как проходит работа?</strong><small>{template.questions.length} коротких вопроса · можно ответить позже</small></span><ArrowRight size={20}/></button>{e.checkins.length>0&&<p className="small muted">Последний контакт: {stamp(e.checkins.at(-1)!.at)}</p>}</section><aside className="employee-aside"><div className="contact-box"><p className="eyebrow">Наставник</p><div className="user-row"><span className="avatar">{e.mentor.split(' ').map(x=>x[0]).join('')}</span><div><h3>{e.mentor}</h3><small>Ваш наставник</small></div></div><p>Поможет разобраться с ближайшей задачей и найти нужного человека.</p><button className="secondary" onClick={()=>ask()}>Задать вопрос <ChatCircle size={17}/></button></div><div className="plain-section"><h3>Результат этапа</h3><p>{template.goal}</p><small className="muted">Если нужна помощь с результатом, напишите наставнику</small></div><button className="text-button" onClick={()=>ask('Хочу обсудить вопрос напрямую с HR')}>Написать HR <ArrowRight size={15}/></button></aside></div></>}
 {role==='employee'&&view==='checkin'&&<CheckinForm key={e.id} employee={e} template={template} act={act} busy={busy} done={(q)=>{if(q)ask(q);else{setToast('Ответы сохранены');go('day')}}} back={()=>go('day')}/>}
 {role==='employee'&&view==='ask'&&<AskForm key={`${e.id}-${prefill}`} employee={e} prefill={prefill} initialTried={initialTried} act={act} busy={busy} done={r=>{setToast('Вопрос передан. Договорённость появится здесь.');setSelected(r.id);go('request')}} back={()=>go('myquestions')} answered={()=>{setToast('Ответ сохранён в истории вопросов');go('myquestions')}}/>}
 {view==='myquestions'&&role==='employee'&&<><Heading title="Мои вопросы" sub="Можно вернуться к договорённости и проверить результат." action={<button className="primary" onClick={()=>ask()}>Задать вопрос <Plus size={18}/></button>}/><div className="panel">{data.requests.length?data.requests.map(r=><button key={r.id} className="list-row clickable" onClick={()=>openRequest(r)}><ChatCircle size={24}/><div className="grow"><strong>{r.category}</strong><p>{r.text}</p><small className="muted">{r.recipient==='hr'?'Елена · HR':e.mentor} · {stamp(r.updatedAt)}</small></div><Badge tone={r.status}>{statuses[r.status]}</Badge><CaretRight size={18}/></button>):<Empty>Пока нет открытых вопросов. Готовые ответы можно найти в базе.</Empty>}</div>{data.inquiries.some(i=>i.outcome==='helped')&&<section className="section"><h2>Ответы, которые помогли</h2>{data.inquiries.filter(i=>i.outcome==='helped').map(i=><div className="list-row" key={i.id}><CheckCircle size={22}/><div><strong>{i.question}</strong><small className="muted">Решено с помощью базы ответов · {stamp(i.at)}</small></div></div>)}</section>}</>}
 {view==='today'&&role!=='employee'&&<><Heading title="Сегодня" sub={new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})} action={role==='hr'?<button className="primary" onClick={addEmployee}><Plus size={18}/>Добавить новичка</button>:undefined}/><div className="summary-line"><span><b>{data.requests.filter(r=>r.status==='new').length}</b> без ответа</span><span><b>{data.requests.filter(r=>r.status==='waiting').length}</b> на подтверждении</span><span><b>{data.inquiries.filter(i=>i.outcome==='helped').length}</b> {plural(data.inquiries.filter(i=>i.outcome==='helped').length,'раз','раза','раз')} помогла база ответов</span></div><div className="desk-layout"><section className="panel"><div className="section-head"><h2>Вопросы сотрудников</h2><span className="small muted">{data.requests.filter(r=>r.status!=='resolved').length} в работе</span></div>{data.requests.filter(r=>r.status!=='resolved').length?data.requests.filter(r=>r.status!=='resolved').map(r=>{const p=data.employees.find(e=>e.id===r.employeeId)!;return <button className="request-row" key={r.id} onClick={()=>openRequest(r)}><span className="avatar">{p.name[0]}</span><div><strong>{p.name}</strong><small>{tracks[templateFor(p).track]} · День {p.day}</small></div><div className="request-topic"><p>{r.text}</p>{r.recipient==='hr'&&<small><LockSimple size={12}/> Напрямую HR</small>}</div><div className="request-owner"><span>{r.owner||'Нужно назначить'}</span><Badge tone={r.due&&r.due<today()?'overdue':r.status}>{r.due&&r.due<today()&&r.status!=='waiting'?'Срок прошёл':statuses[r.status]}</Badge></div><CaretRight size={19}/></button>}):<Empty>Сейчас нет вопросов, которым нужен следующий шаг.</Empty>}</section><aside className="panel contacts"><h2>Ближайшие контакты</h2>{data.requests.filter(r=>r.due&&r.status!=='resolved').map(r=><button className="contact-row" key={r.id} onClick={()=>openRequest(r)}><Clock size={20}/><div><strong>{r.due}</strong><span>{data.employees.find(e=>e.id===r.employeeId)?.name}</span><small>{r.action}</small></div></button>)}{!data.requests.some(r=>r.due&&r.status!=='resolved')&&<p className="muted small">Появятся после того, как вы договоритесь о действии и сроке.</p>}<small className="muted">По договорённости с сотрудником</small></aside></div><button className="neutral-strip" onClick={()=>go('people')}><Info size={22}/><strong>{data.employees.filter(e=>!e.checkins.length).length} сотрудников ещё не ответили</strong><span>Не считается проблемой</span><span className="grow"/><span className="underlined">Посмотреть</span></button>{data.requests.some(r=>r.status==='resolved')&&<section className="section"><h2>Помощь сработала</h2>{data.requests.filter(r=>r.status==='resolved').map(r=><button className="list-row clickable" key={r.id} onClick={()=>openRequest(r)}><CheckCircle size={22}/><div><strong>{data.employees.find(e=>e.id===r.employeeId)?.name}</strong><p>{r.action}</p></div><Badge tone="resolved">Подтверждено сотрудником</Badge></button>)}</section>}</>}
 {view==='people'&&role!=='employee'&&<People data={data} selected={selected} select={setSelected} openRequest={openRequest} add={role==='hr'?addEmployee:undefined} editTemplate={t=>{setEditing(t);go('editor')}}/>}
 {view==='templates'&&role!=='employee'&&<><Heading title="Маршруты адаптации" sub="Один проверенный маршрут — для всей группы. Прогресс каждого остаётся личным." action={role==='hr'?<button className="primary" onClick={()=>{setEditing(null);go('editor')}}><Plus size={18}/>Новый маршрут</button>:undefined}/><div className="template-grid">{data.templates.map(t=><section className="panel template-card" key={t.id}><div className="section-head"><Badge>{tracks[t.track]}</Badge><span className="small muted">Версия {t.version}</span></div><h2>{t.name}</h2><p className="muted">{t.goal}</p><div className="template-meta"><span>{formats[t.format]}</span><span>{t.steps.length} {plural(t.steps.length,'шаг','шага','шагов')} · {t.questions.length} {plural(t.questions.length,'вопрос','вопроса','вопросов')}</span></div><div className="template-footer"><small>{data.employees.filter(e=>e.templateId===t.id).length} {plural(data.employees.filter(e=>e.templateId===t.id).length,'сотрудник','сотрудника','сотрудников')} на маршруте</small><button className="text-button" onClick={()=>{setEditing(t);go('editor')}}>{role==='hr'?'Открыть и изменить':'Посмотреть'}<ArrowRight size={17}/></button></div></section>)}</div></>}
 {view==='editor'&&role!=='employee'&&<TemplateEditor key={editing?.id||'new'} initial={editing} role={role} act={act} busy={busy} onError={showError} back={()=>go('templates')} saved={()=>{setToast('Маршрут сохранён. Его можно назначать новым сотрудникам.');go('templates')}}/>}
 {view==='request'&&(()=>{const r=data.requests.find(r=>r.id===selected);if(!r)return <Empty>Вопрос недоступен в этой роли. Вернитесь к списку.</Empty>;const p=data.employees.find(e=>e.id===r.employeeId)!;return <RequestDetail key={r.id} request={r} employee={p} role={role} data={data} act={act} busy={busy} back={()=>go(role==='employee'?'myquestions':'today')} publish={()=>{setArticle({id:'',track:templateFor(p).track,title:r.category,answer:'',keywords:'',status:'draft',helpful:0,notHelpful:0,updatedAt:'',source:'',sourceRequestId:r.id});setModal('article')}}/>})()}
 {view==='knowledge'&&<Knowledge data={data} role={role} track={template.track} open={openArticle} ask={ask} act={act} employee={e} busy={busy} notify={setToast}/>}
 <footer className="page-footer"><span>Разбег · первые недели в команде</span><button className="text-button" onClick={()=>setModal('about')}>О сервисе <Info size={14}/></button></footer></main></div>
 {toast&&<div className="toast" role="status"><CheckCircle size={20}/>{toast}</div>}
 {modal==='employee'&&<EmployeeModal templates={data.templates} act={act} busy={busy} close={()=>setModal('')} onError={showError} saved={()=>{setModal('');setToast('Новичок добавлен. Общий маршрут назначен.');go('people')}}/>}
 {modal==='article'&&<ArticleModal key={article?.id||article?.sourceRequestId||'new'} initial={article} role={role} act={act} busy={busy} close={()=>setModal('')} saved={()=>{setModal('');setToast('Ответ сохранён в базе');}}/>}
 {modal==='step'&&(()=>{const step=template.steps.find(s=>s.id===selected);return step?<Modal title={step.title} close={()=>setModal('')}><Badge>{step.stage}</Badge><p className="modal-copy">{step.detail}</p>{template.track==='warehouse'&&<div className="note"><Info size={18}/><span>Для рабочего допуска и операций с оборудованием следуйте очным инструкциям уполномоченного сотрудника. Отметка здесь их не заменяет.</span></div>}<p className="small muted">Основание: {step.basis}</p><div className="modal-actions"><button className="secondary" onClick={()=>{setModal('');ask(`Нужна помощь с шагом: ${step.title}`)}}>Нужна помощь</button><button className="primary" disabled={busy} onClick={()=>act('completeStep',{employeeId:e.id,stepId:step.id,done:!e.completed.includes(step.id)}).then(()=>{setModal('');setToast('Шаг обновлён')}).catch(()=>{})}>{e.completed.includes(step.id)?'Вернуть в план':'Отметить шаг'}<Check size={17}/></button></div></Modal>:null})()}
 {modal==='about'&&<Modal title="О подходе и демонстрации" close={()=>setModal('')}><p>Короткий план по роли, первая практическая задача и помощь с препятствиями. Демо работает локально; записи хранятся в SQLite на этом компьютере.</p><div className="note"><Info size={20}/><span>Роли переключаются открыто для проверки. Это не production-авторизация. Используйте вымышленные данные. Внешние сообщения и интеграция с Битрикс24 не подключены.</span></div><p>Файлы разбираются на этом компьютере без отправки во внешние ИИ-сервисы. Оригиналы и текст резюме не сохраняются. Описание вакансии сохраняется только при сохранении маршрута.</p><p>План составляется по прозрачным правилам из текста и шаблона, а не внешней языковой моделью. Проверьте его перед назначением. Это инструмент поддержки, не оценка сотрудника и не доказанное средство снижения текучести.</p><h3>Источники</h3>{data.sources.map(s=><div className="source" key={s.url}><a href={s.url} target="_blank" rel="noreferrer">{s.title}<ArrowRight size={15}/></a><small>{s.detail}</small></div>)}<button className="secondary danger" onClick={()=>{setModal('');reset()}}>Сбросить учебные данные</button></Modal>}
 </>;
}

function CheckinForm({employee,template,act,busy,done,back}:{employee:Employee;template:Template;act:Act;busy:boolean;done:(q?:string)=>void;back:()=>void}){
 const [answers,setAnswers]=useState<Record<string,string>>({}),[comment,setComment]=useState(''),[key]=useState(uid),[error,setError]=useState('');const [step,setStep]=useState(0);const q=template.questions[step];
 const options=[['yes','Да, всё понятно'],['partial','Частично'],['no','Пока нет'],['notyet','Ещё не требовалось'],['irrelevant','К моей работе не относится']];
 const submit=async()=>{if(template.questions.some(q=>!answers[q.id])){setError('Ответьте на каждый вопрос');return}try{await act('checkin',{employeeId:employee.id,key,stage:employee.day<8?'Первая неделя':`День ${employee.day}`,answers:template.questions.map(q=>({questionId:q.id,value:answers[q.id]})),comment});const issue=template.questions.filter(q=>['partial','no','irrelevant'].includes(answers[q.id]));done(issue.length?`${issue.map(q=>`${q.text} — ${answers[q.id]==='partial'?'частично':answers[q.id]==='irrelevant'?'не относится к моей работе':'пока нет'}`).join(' ')}${comment?` — ${comment}`:''}`:undefined);}catch(e){setError((e as Error).message)}};
 return <div className="narrow"><button className="back" onClick={back}><ArrowLeft/>Мой день</button><div className="section-head"><span className="eyebrow">Как проходит работа</span><small className="muted">Вопрос {step+1} из {template.questions.length}</small></div><div className="thin-progress"><span style={{width:`${(step+1)/template.questions.length*100}%`}}/></div><h1 className="question-title">{q.text}</h1><div className="answer-options">{options.map(([v,label])=><button key={v} className={answers[q.id]===v?'selected':''} onClick={()=>{setAnswers({...answers,[q.id]:v});setError('')}}><span className="radio-dot"/>{label}</button>)}</div>{step===template.questions.length-1&&<Field label="Что стоит уточнить? · необязательно"><textarea value={comment} onChange={e=>setComment(e.target.value)} maxLength={2000} placeholder="Если захотите, вопрос можно будет передать наставнику или HR."/></Field>}{error&&<p className="error" role="alert">{error}</p>}<div className="form-actions">{step>0&&<button className="secondary" onClick={()=>setStep(step-1)}>Назад</button>}<button className="primary" disabled={busy||!answers[q.id]} onClick={()=>step<template.questions.length-1?setStep(step+1):submit()}>{step<template.questions.length-1?'Далее':'Сохранить ответы'}<ArrowRight size={18}/></button></div><p className="small muted">Ответы доступны HR и наставнику. Личный вопрос можно отдельно направить HR. Обращение не отправляется автоматически.</p><button className="text-button muted" onClick={back}>Ответить позже</button></div>
}

function AskForm({employee,prefill,initialTried,act,busy,done,back,answered}:{employee:Employee;prefill:string;initialTried:string[];act:Act;busy:boolean;done:(r:Request)=>void;back:()=>void;answered:()=>void}){
 const [question,setQuestion]=useState(prefill),[suggestions,setSuggestions]=useState<Article[]|null>(null),[recipient,setRecipient]=useState<'mentor'|'hr'>(prefill.includes('напрямую')?'hr':'mentor'),[selectedArticle,setSelectedArticle]=useState(''),[tried,setTried]=useState<string[]>(initialTried),[error,setError]=useState(''),[searching,setSearching]=useState(false),[key]=useState(uid);
 const search=async()=>{if(!question.trim()){setError('Напишите, какой вопрос возник');return}setSearching(true);setError('');try{const a=await api<Article[]>(`/api/search?employeeId=${employee.id}&q=${encodeURIComponent(question)}`);setSuggestions(a);setSelectedArticle(a[0]?.id||'');}catch(e){setError((e as Error).message)}finally{setSearching(false)}};
 const escalate=async()=>{try{const r=await act('ask',{employeeId:employee.id,key,text:question,recipient,category:recipient==='hr'?'Вопрос к HR':'Рабочий вопрос',triedArticleIds:tried});done(r as Request)}catch(e){setError((e as Error).message)}};
 const a=suggestions?.find(a=>a.id===selectedArticle);
 return <div className="narrow wide-narrow"><button className="back" onClick={back}><ArrowLeft/>Мои вопросы</button><Heading title="Что мешает разобраться?" sub="Сначала проверим готовые ответы. Если не помогут, вопрос можно передать человеку."/><Field label="Ваш вопрос"><textarea autoFocus value={question} maxLength={4000} placeholder="Например: не открывается таблица остатков" onChange={e=>{setQuestion(e.target.value);setSuggestions(null);setTried([])}}/></Field><button className="primary" disabled={searching||busy||!question.trim()} onClick={search}><MagnifyingGlass size={19}/>{searching?'Ищем ответ…':'Найти готовый ответ'}</button>{suggestions!==null&&<section className="section">{suggestions.length?<><p className="eyebrow">Подходящие ответы</p><div className="suggestion-tabs">{suggestions.map(s=><button className={selectedArticle===s.id?'selected':''} key={s.id} onClick={()=>setSelectedArticle(s.id)}>{s.title}</button>)}</div>{a&&<div className="answer-box"><Badge tone="published">Проверенный ответ · {a.source}</Badge><h2>{a.title}</h2><p className="preline">{a.answer}</p><div className="form-actions"><button className="primary" disabled={busy} onClick={()=>act('articleFeedback',{employeeId:employee.id,articleId:a.id,question,key:`${key}-${a.id}-yes`,helpful:true}).then(answered).catch(e=>setError((e as Error).message))}>Да, помогло <Check size={18}/></button><button className="secondary" disabled={busy||tried.includes(a.id)} onClick={()=>act('articleFeedback',{employeeId:employee.id,articleId:a.id,question,key:`${key}-${a.id}-no`,helpful:false}).then(()=>setTried([...new Set([...tried,a.id])])).catch(e=>setError((e as Error).message))}>{tried.includes(a.id)?'Отметили: нужен человек':'Не помогло'}</button></div></div>}</>:<div className="note"><Info size={20}/><span>Подходящего проверенного ответа пока нет. Вопрос можно передать наставнику или HR.</span></div>}</section>}<div className="section human-contact"><h3>{suggestions===null?'Или сразу человеку':'Нужна дополнительная помощь?'}</h3><div className="recipient-options"><button className={recipient==='mentor'?'selected':''} onClick={()=>setRecipient('mentor')}><Users size={20}/><span>Наставнику<small>{employee.mentor}</small></span></button><button className={recipient==='hr'?'selected':''} onClick={()=>setRecipient('hr')}><LockSimple size={20}/><span>Напрямую HR<small>Елена · HR</small></span></button></div><p className="small muted">Текст получит {recipient==='hr'?'HR. В очередь наставника он не попадёт.':`${employee.mentor}. Для личного вопроса выберите HR.`} {tried.length>0&&'Передадим также, какие ответы не помогли.'}</p><button className="secondary" disabled={busy||!question.trim()} onClick={escalate}>Передать вопрос <ArrowRight size={18}/></button></div>{error&&<p role="alert" className="error">{error}</p>}</div>
}

function People({data,selected,select,openRequest,add,editTemplate}:{data:State;selected:string;select:(s:string)=>void;openRequest:(r:Request)=>void;add?:()=>void;editTemplate:(t:Template)=>void}){
 const [filter,setFilter]=useState('all'),[query,setQuery]=useState('');const people=data.employees.filter(e=>(filter==='all'||data.templates.find(t=>t.id===e.templateId)?.track===filter)&&e.name.toLowerCase().includes(query.toLowerCase()));const p=people.find(e=>e.id===selected)||people[0];const t=p&&data.templates.find(t=>t.id===p.templateId)!;const requests=data.requests.filter(r=>r.employeeId===p?.id&&r.status!=='resolved');
 return <><Heading title="Мои новички" sub="Один маршрут для должности. Личный прогресс и помощь — для каждого." action={add&&<button className="primary" onClick={add}><Plus size={18}/>Добавить новичка</button>}/><div className="toolbar"><div className="filter-tabs">{[['all','Все'],...Object.entries(tracks)].map(([v,label])=><button className={filter===v?'active':''} key={v} onClick={()=>setFilter(v)}>{label}</button>)}</div><input className="search-input" aria-label="Найти сотрудника" placeholder="Найти по имени" value={query} onChange={e=>setQuery(e.target.value)}/></div>{!p?<Empty>Никого не нашли. Измените фильтр или добавьте сотрудника.</Empty>:<div className="people-layout"><aside className="person-list">{people.map(e=><button className={e.id===p.id?'active':''} key={e.id} onClick={()=>select(e.id)}><span className="avatar">{e.name[0]}</span><span><strong>{e.name}</strong><small>{tracks[data.templates.find(t=>t.id===e.templateId)!.track]} · День {e.day}</small><span className="small muted">{data.requests.some(r=>r.employeeId===e.id&&r.status!=='resolved')?'Есть вопрос в работе':e.checkins.length?'Контакт состоялся':'Контакт ещё впереди'}</span></span></button>)}</aside><section className="panel dossier"><div className="section-head"><div><h2>{p.name}</h2><p className="muted">{p.role} · {formats[t.format]} · День {p.day}</p></div><Badge>{p.completed.filter(s=>t.steps.some(x=>x.id===s)).length} из {t.steps.length} шагов</Badge></div><Journey completed={p.completed.filter(s=>t.steps.some(x=>x.id===s)).length} total={t.steps.length}/><h3>Результат этапа</h3><p>{t.goal}</p><div className="step-list">{t.steps.map(s=><div className="step-row" key={s.id}><span className={`check-circle ${p.completed.includes(s.id)?'checked':''}`}>{p.completed.includes(s.id)&&<Check size={14}/>}</span><span>{s.title}</span><Badge tone={p.completed.includes(s.id)?'resolved':'neutral'}>{p.completed.includes(s.id)?'Отмечено сотрудником':'В плане'}</Badge></div>)}</div>{requests.length>0&&<section className="section"><h3>Следующий шаг по вопросу</h3>{requests.map(r=><button className="next-action" key={r.id} onClick={()=>openRequest(r)}><div><strong>{r.action||r.text}</strong><small>{r.owner||'Нужен ответ ответственного'}{r.due?` · ${r.due}`:''}</small></div><ArrowRight size={20}/></button>)}</section>}<div className="dossier-bottom"><span className="small muted">Наставник: {p.mentor}</span><button className="text-button" onClick={()=>editTemplate(t)}>Посмотреть маршрут <ArrowRight size={16}/></button></div><details className="section"><summary>Последний короткий контакт {p.checkins.length?`· ${stamp(p.checkins.at(-1)!.at)}`:''}</summary>{p.checkins.length?<>{p.checkins.at(-1)!.answers.map(a=><p className="small" key={a.questionId}>{a.question||t.questions.find(q=>q.id===a.questionId)?.text||'Вопрос предыдущей версии'}<br/><strong>{{yes:'Да',partial:'Частично',no:'Пока нет',notyet:'Ещё не требовалось',irrelevant:'Не относится'}[a.value]}</strong></p>)}<p>{p.checkins.at(-1)!.comment}</p></>:<p className="small muted">Ответов пока нет. Это не считается проблемой или оценкой человека.</p>}</details></section></div>}</>;
}

function RequestDetail({request:r,employee:e,role,data,act,busy,back,publish}:{request:Request;employee:Employee;role:Role;data:State;act:Act;busy:boolean;back:()=>void;publish:()=>void}){
 const [action,setAction]=useState(r.action),[owner,setOwner]=useState(r.owner||(role==='hr'?'Елена · HR':e.mentor)),[due,setDue]=useState(r.due||today()),[message,setMessage]=useState(''),[error,setError]=useState('');
 const save=async(status:string)=>{try{await act('updateRequest',{requestId:r.id,action,owner,due,status});}catch(e){setError((e as Error).message)}};
 const send=async(ev:FormEvent)=>{ev.preventDefault();try{await act('requestMessage',{requestId:r.id,employeeId:e.id,text:message});setMessage('')}catch(e){setError((e as Error).message)}};
 return <><button className="back" onClick={back}><ArrowLeft/>К вопросам</button><Heading title={r.category} sub={`${e.name} · ${e.role} · День ${e.day}`} action={<Badge tone={r.status}>{statuses[r.status]}</Badge>}/><div className="thread-layout"><section><div className="thread">{r.messages.map(m=><article className={`message ${m.author===e.name?'employee-message':''}`} key={m.id}><p className="small"><strong>{m.author}</strong><span className="muted"> · {stamp(m.at)}</span></p><p className="preline">{m.text}</p></article>)}</div>{r.triedArticleIds.length>0&&<details className="section"><summary>Готовые ответы, которые не помогли</summary>{r.triedArticleIds.map(id=><p key={id} className="small">{data.articles.find(a=>a.id===id)?.title||'Ответ из базы'}</p>)}</details>}{role==='employee'&&r.status==='waiting'&&<div className="confirmation"><h3>Вопрос решён?</h3><p>Подтвердите, получилось ли продолжить работу.</p><div className="form-actions"><button className="primary" disabled={busy} onClick={()=>act('confirmRequest',{requestId:r.id,employeeId:e.id,helpful:true}).catch(err=>setError(err.message))}>Да, помогло <Check size={17}/></button><button className="secondary" disabled={busy} onClick={()=>act('confirmRequest',{requestId:r.id,employeeId:e.id,helpful:false}).catch(err=>setError(err.message))}>Пока нет</button></div></div>}<form className="message-form" onSubmit={send}><input aria-label="Добавить сообщение" placeholder="Добавить сообщение" maxLength={4000} value={message} onChange={e=>setMessage(e.target.value)}/><button className="secondary" disabled={busy||!message.trim()}><PaperPlaneTilt size={19}/><span>Отправить</span></button></form></section><aside className="panel agreement"><h2>Договорённость</h2>{role==='employee'||r.status==='resolved'?<><div className="agreement-item"><small>Действие</small><p>{r.action||'Ответственный ещё не назначил действие'}</p></div><div className="agreement-item"><small>Кто поможет</small><p>{r.owner||(r.recipient==='hr'?'Елена · HR':e.mentor)}</p></div><div className="agreement-item"><small>Следующий контакт</small><p>{r.due||'Пока не назначен'}</p></div></>:<><Field label="Что сделать"><textarea value={action} maxLength={2000} onChange={e=>setAction(e.target.value)} placeholder="Конкретное действие, о котором договорились"/></Field><Field label="Ответственный"><input value={owner} maxLength={100} onChange={e=>setOwner(e.target.value)}/></Field><Field label="Срок следующего шага"><input type="date" value={due} onChange={e=>setDue(e.target.value)}/></Field><button className="secondary full" disabled={busy||!action.trim()||!owner.trim()||!due} onClick={()=>save('progress')}>Сохранить договорённость</button><button className="primary full" disabled={busy||!action.trim()||!owner.trim()||!due} onClick={()=>save('waiting')}>Сделано → проверить</button></>}<div className="note"><Info size={18}/><span>{r.status==='resolved'?'Сотрудник подтвердил результат.':'Вопрос завершится после подтверждения сотрудника. Если помощь не сработала, продолжим работу.'}</span></div>{role==='hr'&&<button className="text-button" onClick={publish}>{r.linkedArticleId?'Подготовить ещё один ответ':'Подготовить ответ для базы'}<Books size={17}/></button>}{role==='hr'&&<p className="small muted">Публикуйте обобщённый ответ после проверки, без имени и личной истории.</p>}</aside></div>{error&&<p className="error" role="alert">{error}</p>}</>;
}

function Knowledge({data,role,track,open,ask,act,employee,busy,notify}:{data:State;role:Role;track:Track;open:(a:Article|null)=>void;ask:(q:string,articleId?:string)=>void;act:Act;employee:Employee;busy:boolean;notify:(s:string)=>void}){
 const [query,setQuery]=useState(''),[filter,setFilter]=useState<string>(role==='employee'?track:'all'),[status,setStatus]=useState('all'),[expanded,setExpanded]=useState(''),[error,setError]=useState('');
 const list=data.articles.filter(a=>(role!=='employee'||[track,'all'].includes(a.track))&&(filter==='all'||a.track===filter||a.track==='all')&&(status==='all'||a.status===status)&&`${a.title} ${a.answer} ${a.keywords}`.toLowerCase().includes(query.toLowerCase()));
 return <><Heading title={role==='employee'?'Готовые ответы':'База проверенных ответов'} sub={role==='employee'?'Начните здесь. Если ответ не подходит, рядом есть человек.':'Повторяющиеся вопросы становятся общими ответами — после проверки HR.'} action={role==='hr'?<button className="primary" onClick={()=>open(null)}><Plus size={18}/>Добавить ответ</button>:undefined}/><div className="toolbar"><div className="search-wrap"><MagnifyingGlass size={20}/><input aria-label="Найти ответ" placeholder="Поиск ответов" value={query} onChange={e=>setQuery(e.target.value)}/></div>{role!=='employee'&&<><select aria-label="Направление ответа" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Все направления</option>{Object.entries(tracks).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select aria-label="Статус ответа" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Все статусы</option><option value="published">Опубликовано</option><option value="draft">Черновики</option></select></>}</div><div className="panel">{list.length?list.map(a=><article className="faq-item" key={a.id}><button className="faq-title" aria-expanded={expanded===a.id} onClick={()=>setExpanded(expanded===a.id?'':a.id)}><Books size={21}/><strong>{a.title}</strong><Badge tone={a.status}>{a.status==='draft'?'Черновик':a.track==='all'?'Для всех':tracks[a.track]}</Badge><Plus size={18} className={expanded===a.id?'rotate':''}/></button>{expanded===a.id&&<div className="faq-answer"><p className="preline">{a.answer}</p><small className="muted">{a.source} · {stamp(a.updatedAt)}</small><div className="form-actions">{role==='hr'?<><button className="text-button" onClick={()=>open(a)}><PencilSimple size={17}/>Изменить</button><span className="small muted">Помогло: {a.helpful} · Не помогло: {a.notHelpful}</span></>:role==='employee'?<><button className="secondary" disabled={busy} onClick={()=>act('articleFeedback',{employeeId:employee.id,articleId:a.id,helpful:true,key:`kb-${employee.id}-${a.id}-yes`,question:a.title}).then(()=>notify('Ответ отмечен как полезный')).catch(e=>setError(e.message))}>Помогло <Check size={16}/></button><button className="text-button" disabled={busy} onClick={()=>act('articleFeedback',{employeeId:employee.id,articleId:a.id,helpful:false,key:`kb-${employee.id}-${a.id}-no`,question:a.title}).then(()=>ask(a.title,a.id)).catch(e=>setError(e.message))}>Не помогло — задать вопрос <ArrowRight size={16}/></button></>:null}</div></div>}</article>):<Empty>Ответов не нашли. {role==='employee'?'Можно задать вопрос наставнику или HR.':'Попробуйте другой поиск или добавьте проверенный ответ.'}</Empty>}</div>{role==='employee'&&<button className="secondary section" onClick={()=>ask(query)}>Не нашли ответ? Задайте вопрос <ArrowRight size={18}/></button>}{error&&<p className="error" role="alert">{error}</p>}</>;
}

async function readDocument(file:File):Promise<{text:string;filename:string;characters:number}>{if(file.size>8*1024*1024)throw new Error('До 8 МБ на файл');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let n=0;n<bytes.length;n+=0x8000)binary+=String.fromCharCode(...bytes.subarray(n,n+0x8000));return api('/api/document',{filename:file.name,base64:btoa(binary)});}
function DocumentUpload({label,onText}:{label:string;onText:(text:string,name:string)=>void}){const [busy,setBusy]=useState(false),[error,setError]=useState(''),[name,setName]=useState('');return <div className="document-upload"><label className={`upload-button ${busy?'disabled':''}`}><UploadSimple size={19}/>{busy?'Извлекаем текст…':label}<input aria-label={label} type="file" accept=".pdf,.doc,.docx,.txt" disabled={busy} onChange={async e=>{const f=e.target.files?.[0];if(!f)return;setBusy(true);setError('');try{const d=await readDocument(f);setName(d.filename);onText(d.text,d.filename)}catch(e){setError((e as Error).message)}finally{setBusy(false);e.target.value=''}}}/></label><small className="muted">PDF, DOC, DOCX, TXT · до 8 МБ · без отправки во внешние сервисы</small>{name&&<small className="file-success"><FileText size={15}/>{name}</small>}{error&&<p className="error" role="alert">{error}</p>}</div>}

const sample='Аналитик маркетплейсов RAGEX. Удалённая работа. Анализ продаж и остатков, подготовка отчётов. Взаимодействие с отделом продаж. Работа с таблицами и кабинетом маркетплейса.';
function TemplateEditor({initial,role,act,busy,onError,back,saved}:{initial:Template|null;role:Role;act:Act;busy:boolean;onError:(e:unknown)=>void;back:()=>void;saved:()=>void}){
 const [source,setSource]=useState(initial?.source||''),[draft,setDraft]=useState<Template|null>(initial),[working,setWorking]=useState(false),[reviewed,setReviewed]=useState(false),[error,setError]=useState('');
 const analyse=async()=>{setWorking(true);setError('');try{const t=await api<Template>('/api/analyse',{text:source});setDraft({...t,id:initial?.id||''});setReviewed(false);}catch(e){setError((e as Error).message)}finally{setWorking(false)}};
 const submit=async()=>{if(!draft||!reviewed)return;try{await act('saveTemplate',{...draft,source});saved()}catch(e){setError((e as Error).message);onError(e)}};
 const update=<K extends keyof Template>(k:K,v:Template[K])=>{if(draft)setDraft({...draft,[k]:v});setReviewed(false)};
 return <><button className="back" onClick={back}><ArrowLeft/>Маршруты</button><Heading title={initial?'Маршрут адаптации':'Новый маршрут адаптации'} sub="Вставьте описание работы — проверьте предложенный план. Один маршрут можно назначить всей группе."/><div className="wizard-steps"><span className={!draft?'active':''}>1 <b>Контекст</b></span><CaretRight size={16}/><span className={draft?'active':''}>2 <b>Проверка</b></span><CaretRight size={16}/><span>3 <b>Назначение</b></span></div><div className="editor-layout"><section className="panel source-panel"><h2>Исходное описание</h2><Field label="Вакансия или обязанности"><textarea className="source-input" value={source} maxLength={40000} onChange={e=>{setSource(e.target.value);setReviewed(false)}} placeholder="Обязанности, формат работы, инструменты и ожидания от сотрудника" readOnly={role!=='hr'}/></Field>{role==='hr'&&<><DocumentUpload label="Загрузить описание" onText={t=>{setSource(t);setReviewed(false)}}/><div className="form-actions"><button className="primary" disabled={working||!source.trim()} onClick={analyse}>{working?'Разбираем…':'Разобрать описание'}<ArrowRight size={18}/></button><button className="text-button" onClick={()=>{setSource(sample);setReviewed(false)}}>Готовый пример</button></div></>}<p className="small muted section">План предлагается по прозрачным правилам и темам адаптации. Внешний ИИ не подключён. Неподтверждённые сведения нужно уточнить.</p>{draft&&<><Field label="Направление"><select disabled={role!=='hr'} value={draft.track} onChange={e=>update('track',e.target.value as Track)}>{Object.entries(tracks).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Формат работы"><select disabled={role!=='hr'} value={draft.format} onChange={e=>{const format=e.target.value as Format;const steps=draft.steps.map((s,i)=>i===0?{...s,title:format==='remote'?'Познакомиться с командой онлайн':format==='hybrid'?'Согласовать знакомство с командой и первый выход':'Познакомиться с командой и площадкой'}:s);setDraft({...draft,format,steps});setReviewed(false)}}><option value="unknown">Нужно уточнить</option><option value="onsite">На площадке</option><option value="remote">Удалённо</option><option value="hybrid">Гибридно</option></select></Field><Field label="Опыт — подтвердите вручную"><input value={draft.experience} readOnly={role!=='hr'} onChange={e=>update('experience',e.target.value)}/></Field><Field label="Наставник"><input value={draft.mentor} maxLength={100} readOnly={role!=='hr'} onChange={e=>update('mentor',e.target.value)}/></Field></>}</section><section className="panel plan-panel"><h2>{draft?'Предложенный план':'План появится здесь'}</h2>{!draft?<Empty>Вставьте описание или загрузите файл. Затем нажмите «Разобрать описание».</Empty>:<><Field label="Название маршрута"><input value={draft.name} maxLength={160} readOnly={role!=='hr'} onChange={e=>update('name',e.target.value)}/></Field><Field label="Практический результат этапа"><textarea value={draft.goal} maxLength={500} readOnly={role!=='hr'} onChange={e=>update('goal',e.target.value)}/></Field><h3>Шаги</h3>{draft.steps.map((s,i)=><div className="editable-step" key={s.id}><div className="section-head"><Badge>{s.stage}</Badge>{role==='hr'&&draft.steps.length>1&&<button className="icon-button" aria-label={`Удалить шаг ${i+1}`} onClick={()=>update('steps',draft.steps.filter((_,n)=>n!==i))}><Trash size={17}/></button>}</div><input aria-label={`Название шага ${i+1}`} value={s.title} maxLength={240} readOnly={role!=='hr'} onChange={e=>update('steps',draft.steps.map((x,n)=>n===i?{...x,title:e.target.value}:x))}/><details><summary>Описание и основание</summary><textarea aria-label={`Описание шага ${i+1}`} value={s.detail} maxLength={2000} readOnly={role!=='hr'} onChange={e=>update('steps',draft.steps.map((x,n)=>n===i?{...x,detail:e.target.value}:x))}/><small className="muted">{s.basis}</small></details></div>)}{role==='hr'&&draft.steps.length<12&&<button className="text-button" onClick={()=>update('steps',[...draft.steps,{id:uid(),title:'Новый шаг',detail:'',stage:'Первая задача',basis:'Добавлено HR'}])}><Plus size={17}/>Добавить шаг</button>}<details className="section"><summary>Вопросы короткого контакта · {draft.questions.length}</summary><div className="section">{draft.questions.map((q,i)=><div className="editable-question" key={q.id}><Field label={`Вопрос ${i+1}`} hint={q.basis}><input value={q.text} maxLength={400} readOnly={role!=='hr'} onChange={e=>update('questions',draft.questions.map((x,n)=>n===i?{...x,text:e.target.value}:x))}/></Field>{role==='hr'&&draft.questions.length>1&&<button aria-label={`Удалить вопрос ${i+1}`} className="icon-button" onClick={()=>update('questions',draft.questions.filter((_,n)=>n!==i))}><Trash size={17}/></button>}</div>)}</div></details>{draft.notes&&<div className="note"><Info size={18}/><span>{draft.notes}</span></div>}{role==='hr'&&<><label className="check-label"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/><span>Проверил(а) формат, задачи и вопросы. В плане нет неподтверждённых правил.</span></label>{initial&&<p className="small muted">Изменения общего маршрута увидят все назначенные на него сотрудники. Уже отмеченные неизменённые шаги сохранятся.</p>}<button className="primary full" disabled={busy||!reviewed||draft.format==='unknown'||draft.steps.some(s=>!s.title.trim())||!draft.name.trim()} onClick={submit}>Подтвердить и сохранить маршрут <Check size={18}/></button></>}</>}{error&&<p className="error" role="alert">{error}</p>}</section></div></>;
}

function EmployeeModal({templates,act,busy,close,saved,onError}:{templates:Template[];act:Act;busy:boolean;close:()=>void;saved:()=>void;onError:(e:unknown)=>void}){
 const [key]=useState(uid);const [name,setName]=useState(''),[job,setJob]=useState(''),[templateId,setTemplateId]=useState(templates[0]?.id||''),[startDate,setStart]=useState(today()),[resume,setResume]=useState(''),[filename,setFilename]=useState(''),[error,setError]=useState('');
 const submit=async(ev:FormEvent)=>{ev.preventDefault();try{await act('createEmployee',{name,job,templateId,startDate,key});saved()}catch(e){setError((e as Error).message);onError(e)}};
 return <Modal title="Добавить новичка" close={close}><p className="muted">Выберите готовый маршрут. Для сотрудников одной должности не нужно настраивать всё заново.</p><form onSubmit={submit}><Field label="Имя сотрудника"><input autoFocus required maxLength={100} value={name} onChange={e=>setName(e.target.value)} placeholder="Вымышленное имя для проверки"/></Field><Field label="Маршрут должности"><select required value={templateId} onChange={e=>setTemplateId(e.target.value)}>{templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></Field><div className="form-grid"><Field label="Должность · можно оставить из маршрута"><input value={job} maxLength={120} onChange={e=>setJob(e.target.value)}/></Field><Field label="Дата выхода"><input required type="date" value={startDate} onChange={e=>setStart(e.target.value)}/></Field></div><details className="resume-section"><summary><FileText size={18}/>Резюме · необязательно</summary><p className="small muted">Поможет вручную проверить опыт и выбрать подходящий маршрут. Система не оценивает кандидата. Текст резюме не сохраняется.</p><DocumentUpload label="Загрузить резюме" onText={(t,n)=>{setResume(t);setFilename(n)}}/>{resume&&<Field label={`Извлечённый текст · ${filename}`}><textarea className="resume-preview" readOnly value={resume}/></Field>}</details>{error&&<p className="error" role="alert">{error}</p>}<div className="modal-actions"><button className="secondary" type="button" onClick={close}>Отмена</button><button className="primary" disabled={busy||!name.trim()}>Назначить маршрут <ArrowRight size={18}/></button></div></form></Modal>;
}

function ArticleModal({initial,role,act,busy,close,saved}:{initial:Article|null;role:Role;act:Act;busy:boolean;close:()=>void;saved:()=>void}){
 const [title,setTitle]=useState(initial?.title||''),[answer,setAnswer]=useState(initial?.answer||''),[keywords,setKeywords]=useState(initial?.keywords||''),[track,setTrack]=useState<Track|'all'>(initial?.track||'all'),[reviewed,setReviewed]=useState(false),[error,setError]=useState('');
 const save=async(status:string)=>{try{await act('saveArticle',{id:initial?.id||'',title,answer,keywords,track,status,reviewed,sourceRequestId:initial?.sourceRequestId||null});saved()}catch(e){setError((e as Error).message)}};
 return <Modal title={initial?.id?'Проверенный ответ':'Новый ответ для базы'} close={close}><p className="muted">Общий ответ без личных сведений. Новые обращения не публикуются автоматически.</p><Field label="Вопрос / заголовок"><input value={title} maxLength={200} readOnly={role!=='hr'} onChange={e=>{setTitle(e.target.value);setReviewed(false)}}/></Field><Field label="Подготовленный ответ"><textarea className="article-input" value={answer} maxLength={6000} readOnly={role!=='hr'} placeholder="Объясните действие понятным языком. Не копируйте личную переписку." onChange={e=>{setAnswer(e.target.value);setReviewed(false)}}/></Field><Field label="Для кого"><select value={track} disabled={role!=='hr'} onChange={e=>{setTrack(e.target.value as Track|'all');setReviewed(false)}}><option value="all">Все направления</option>{Object.entries(tracks).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Ключевые слова для похожих вопросов"><input value={keywords} maxLength={500} readOnly={role!=='hr'} placeholder="Например: доступ, логин, таблица, остатки" onChange={e=>{setKeywords(e.target.value);setReviewed(false)}}/></Field>{role==='hr'&&<><label className="check-label"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/><span>Ответ проверен, актуален и не содержит личных сведений.</span></label><div className="modal-actions"><button className="secondary" disabled={busy||!title.trim()||!answer.trim()} onClick={()=>save('draft')}>Сохранить черновик</button><button className="primary" disabled={busy||!reviewed||!title.trim()||!answer.trim()} onClick={()=>save('published')}>Опубликовать <Check size={18}/></button></div></>}{error&&<p className="error" role="alert">{error}</p>}</Modal>
}
